def generate_character():
    character = {}
    names = random.choice(nameData).split (" | ")

    # Roll 0-9 to choose gender/pronouns and names accordingly.
    roll = random.randint(0,9) 
    if roll <4:
        character["name"] = names[0] + " " + names[2]
        character["pronouns"] = "He/Him"
    elif roll <8:
        character["name"] = names[1] + " " + names[2]
        character["pronouns"] = "She/Her"
    elif roll ==8:
        character["name"] = names[0] + " " + names[2]
        character["pronouns"] = "They/Them"
    else:
        character["name"] = names[0] + " " + names[2]
        character["pronouns"] = "Xey/Xem"

    character["occupation"] = random.choice(occupations)
    character["home"] = random.choice(home)
    character["motivation"] = random.choice(motivations)
    character["quirk"] = random.choice(quirks)

    # Stats: 2d10 + 25 (range 27-45)
    # Saves: 2d10 + 10 (range 12-30)
    # HP: 1d10 + 10
    stat_names = ["STR", "SPD", "INT", "COMBAT"]
    save_names = ["Sanity", "Fear", "Body"]

    for stat in stat_names:
        character[stat] = random.randint(1,10) + random.randint(1,10) +25
    for saves in save_names:
        character[saves] = random.randint(1,10) + random.randint(1,10) +10
    character["HP"] = random.randint(1,10) +10

    return character

def export_to_csv(characters):
    """Save every character generated this session to a CSV file that opens in Excel."""
    if not characters:
        print("\nNo characters to export yet. Generate one first.\n")
        return

    # Timestamp in the filename so each export creates a new file instead of overwriting the last one
    filename = "characters_" + datetime.now().strftime("%Y%m%d_%H%M%S") + ".csv"

    try:
        # utf-8-sig lets Excel display special characters (like ’ and ł in some names) correctly;
        # newline="" prevents blank rows between lines on Windows
        with open(filename, "w", newline="", encoding="utf-8-sig") as file:
            writer = csv.DictWriter(file, fieldnames=characters[0].keys())
            writer.writeheader()
            writer.writerows(characters)
        print(f"\nExported {len(characters)} character(s) to {filename}\n")
    except PermissionError:
        print("\nCould not save the file. Check that the folder isn't read-only and try again.\n")

def get_quantity():
    """Ask how many characters to generate. Repeats until the user enters a valid whole number."""
    while True:
        answer = input("How many characters would you like to generate? (1-100): ")
        # isdigit() rejects letters, decimals, and negative signs before converting to int
        if answer.isdigit() and 1 <= int(answer) <= 100:
            return int(answer)
        print("\nPlease enter a whole number from 1 to 100.\n")

# Stores every character generated this session so option 2 can export them.
characters = []

# Main menu repeats until the user chooses option 3 to exit.
while True:
    choice = input("\nEnter a number to select an option.\n1. Generate character(s).\n2. Export character(s) to excel.\n3. Close program.\n")
    if choice == "1":
        quantity = get_quantity()
        # Generate the requested number of characters and save each one for export.
        for i in range(quantity):
            new_character = generate_character()
            characters.append(new_character)
            print(f"\nCharacter {i + 1}:")
            print(new_character)    
    elif choice == "2":
        export_to_csv(characters)
    elif choice == "3":
        print("\nClosing program.\n")
        break
    else:
        print("\nInvalid input. Please enter 1, 2, or 3.\n")